def transform(grid):
    """Reconstruct the repeated tile pattern and mark each tile's grid coordinate."""
    n = len(grid)
    k = next((x for x in range(1, n + 1) if x * x + x - 1 == n), None)
    if k is None or any(len(row) != n for row in grid):
        raise ValueError("expected a square grid of k*k+k-1 size")
    stride = k + 1

    # Each non-placeholder cell contains the same k-by-k motif. Read one.
    motif = None
    for i in range(k):
        for j in range(k):
            r0, c0 = i * stride, j * stride
            block = [grid[r0 + r][c0:c0 + k] for r in range(k)]
            if any(v == 2 for row in block for v in row) and not any(v == 3 for row in block for v in row):
                motif = [[1 if v == 2 else 0 for v in row] for row in block]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError("no motif found")

    out = [[0 for _ in range(n)] for _ in range(n)]
    # The arrangement of motifs is the motif itself. Fill it, and mark each
    # occupied macro-cell at its corresponding local (row, column) coordinate.
    for i in range(k):
        for j in range(k):
            if not motif[i][j]:
                continue
            r0, c0 = i * stride, j * stride
            for r in range(k):
                for c in range(k):
                    if motif[r][c]:
                        out[r0 + r][c0 + c] = 2
            out[r0 + i][c0 + j] = 8
    return out
